command:
set -eu
export LC_ALL=C
[ -f "$1" ] && [ ! -L "$1" ] || exit 1
/usr/bin/head -c 65536 -- "$1" | (
IFS= read -r first || exit 1
IFS= read -r second || exit 1
case "$first" in
  '{"app":"lsf","child_pid":'*) app=lsf ;;
  '{"app":"native","child_pid":'*) app=native ;;
  *) exit 1 ;;
esac
prefix='{"app":"'"$app"'","child_pid":'
rest=${first#"$prefix"}
child=${rest%%,*}
case "$child" in ''|0*|*[!0-9]*) exit 1 ;; esac
[ "${#child}" -le 10 ] && [ "$child" -le 4294967295 ] || exit 1
record() {
  prefix='{"app":"'"$app"'","child_pid":'"$child"',"detail":'"$4"',"elapsed_nanos":"'
  case "$1" in "$prefix"*) ;; *) return 1 ;; esac
  rest=${1#"$prefix"}
  elapsed=${rest%%\"*}
  case "$elapsed" in ''|*[!0-9]*) return 1 ;; 0) ;; 0*) return 1 ;; esac
  [ "${#elapsed}" -le 18 ] || return 1
  [ "$rest" = "$elapsed\",\"event\":\"$2\",\"schema\":\"latent.optimization.container-event.v1\",\"sequence\":$3,\"wrapper_pid\":1}" ]
}
record "$first" started 0 '{"buffer_bytes_per_direction":16384,"child_kill_wait_millis":5000,"child_listen":"127.0.0.1:7071","child_term_grace_millis":10000,"connect_timeout_millis":5000,"forward_drain_millis":5000,"listen":"0.0.0.0:7070","maximum_connections":32,"maximum_lifetime_millis":300000,"maximum_snapshots":6,"pid1":true,"ready_timeout_millis":30000,"runtime_workers":2}' || exit 1
started_elapsed=$elapsed
case "$app" in
  lsf) detail='{"child_listen":"127.0.0.1:7071","child_status":{"endpoint":"127.0.0.1:7071","event":"ready","nodeId":"optimization-node","ready":true,"schemaVersion":"latent.standalone.status.v1"},"listen":"0.0.0.0:7070"}' ;;
  native) detail='{"child_listen":"127.0.0.1:7071","child_status":{"address":"http://127.0.0.1:7071","event":"ready","implementation":"native-reference"},"listen":"0.0.0.0:7070"}' ;;
esac
record "$second" ready 1 "$detail" || exit 1
[ "$elapsed" -ge "$started_elapsed" ]
)
